import sql from "@/src/utils/db"
import Context from "@/src/utils/koa"
import Router from "koa-router"
import { z } from "zod"

const projects = new Router({
  prefix: "/projects",
})

projects.get("/", async (ctx: Context) => {
  const { orgId } = ctx.state

  const rows = await sql`
    select
      id,
      created_at,
      name,
      org_id,
      exists(select * from run where project_id = project.id) as activated,
      (select api_key from api_key where project_id = project.id and type = 'public') as public_api_key,
      (select api_key from api_key where project_id = project.id and type = 'private') as private_api_key 
    from
      project
    where
      org_id = ${orgId}
  `

  ctx.body = rows
})

projects.post("/", async (ctx: Context) => {
  const { orgId } = ctx.state

  const bodySchema = z.object({
    name: z.string(),
  })
  const { name } = bodySchema.parse(ctx.request.body)

  const [org] = await sql`select * from org where id = ${orgId}`

  if (org.plan === "free") {
    ctx.throw(403, "You can't create more than two project under the free plan")
  }

  const newProject = {
    name,
    orgId,
  }

  const [project] =
    await sql`insert into project ${sql(newProject)} returning *`

  const publicKey = {
    type: "public",
    projectId: project.id,
    apiKey: project.id,
  }
  sql`insert into api_key ${sql(publicKey)}`

  const privateKey = [
    {
      type: "private",
      projectId: project.id,
    },
  ]
  await sql`insert into api_key ${sql(privateKey)}`
  ctx.body = project
})

projects.delete("/:projectId", async (ctx: Context) => {
  const { projectId } = ctx.params
  const { orgId } = ctx.state

  // Check that the project belongs to the current organization
  const [project] = await sql`select id from project where id = ${projectId} and org_id = ${orgId}`
  if (!project) {
    ctx.status = 404
    ctx.body = { error: "Not Found", message: "Project not found" }
    return
  }

  const [{ count }] =
    await sql`select count(*)::int from  project where org_id = ${orgId}`

  if (count > 1) {
    await sql`delete from project where id = ${projectId}`
    ctx.status = 200
  } else {
    ctx.status = 422

    ctx.body = {
      error: "Deletion Failed",
      message: "An organization must have at least one project.",
    }
    return
  }
})

projects.patch("/:projectId", async (ctx: Context) => {
  const { projectId } = ctx.params
  const { orgId } = ctx.state

  // Check that the project belongs to the current organization
  const [project] = await sql`select id from project where id = ${projectId} and org_id = ${orgId}`
  if (!project) {
    ctx.status = 404
    ctx.body = { error: "Not Found", message: "Project not found" }
    return
  }

  const bodySchema = z.object({
    name: z.string(),
  })
  const { name } = bodySchema.parse(ctx.request.body)

  await sql`
      update project
      set
        name = ${name}
      where
        id = ${projectId}
    `
  ctx.status = 200
})

export default projects

import sql from "@/src/utils/db"
import { RESET_PASSWORD, sendVerifyEmail } from "@/src/utils/emails"
import Context from "@/src/utils/koa"
import { sendTelegramMessage } from "@/src/utils/notifications"
import { sendEmail } from "@/src/utils/sendEmail"
import Router from "koa-router"
import { z } from "zod"
import { hashPassword, signJwt, verifyJwt, verifyPassword } from "./utils"

const auth = new Router({
  prefix: "/auth",
})

auth.post("/signup", async (ctx: Context) => {
  const bodySchema = z.object({
    email: z.string().email(),
    password: z.string().min(6),
    name: z.string(),
    orgName: z.string().optional(),
    projectName: z.string().optional(),
    employeeCount: z.string().optional(),
    orgId: z.string().optional(),
    signupMethod: z.enum(["signup", "join"]),
  })

  const {
    email,
    password,
    name,
    orgName,
    projectName,
    employeeCount,
    orgId,
    signupMethod,
  } = bodySchema.parse(ctx.request.body)

  if (orgName?.includes("https://") || name.includes("http://")) {
    ctx.throw(403, "Bad request")
    return
  }

  // Normalize email to lowercase to prevent case-insensitive duplicates
  const normalizedEmail = email.toLowerCase()

  // Use a transaction to ensure atomicity and prevent race conditions
  await sql.begin(async (sql) => {
    const [existingUser] = await sql`
      select * from account where email = ${normalizedEmail}
    `
    if (existingUser) {
      ctx.throw(403, "User already exists")
    }

    if (signupMethod === "signup") {
      const plan = process.env.DEFAULT_PLAN || "free"

      const [org] =
        await sql`insert into org ${sql({ name: orgName || `${name}'s Org`, plan })} returning *`

      const newUser = {
        name,
        passwordHash: await hashPassword(password),
        email: normalizedEmail,
        orgId: org.id,
        role: "admin",
        verified: process.env.SKIP_EMAIL_VERIFY ? true : false,
      }
      const [user] = await sql`
        insert into account ${sql(newUser)} 
        returning *
      `

      const newProject = {
        name: projectName,
        orgId: org.id,
      }
      const [project] = await sql`
        insert into project ${sql(newProject)} returning *
      `

      const publicKey = {
        type: "public",
        projectId: project.id,
        apiKey: project.id,
      }
      await sql`
        insert into api_key ${sql(publicKey)}
      `
      const privateKey = [
        {
          type: "private",
          projectId: project.id,
        },
      ]
      await sql`
        insert into api_key ${sql(privateKey)}
      `

      const token = await signJwt({
        userId: user.id,
        email: user.email,
        orgId: org.id,
      })

      await sendVerifyEmail(normalizedEmail, name)
      await sendTelegramMessage(
        `<b>🔔 New signup from ${normalizedEmail}</b>
        ${name} is ${
          signupMethod === "signup"
            ? `building ${projectName} @ ${orgName} (${employeeCount}).`
            : "joining an org."
        }`,
        "users",
      )

      ctx.body = { token }
    } else if (signupMethod === "join") {
      const newUser = {
        name,
        passwordHash: await hashPassword(password),
        email: normalizedEmail,
        orgId,
        role: "member",
        verified: true,
      }
      const [user] = await sql`insert into account ${sql(newUser)} returning *`

      const token = await signJwt({
        userId: user.id,
        email: user.email,
        orgId,
      })

      ctx.body = { token }
    }
  })
})

auth.post("/login", async (ctx: Context) => {
  const bodySchema = z.object({
    email: z.string().email(),
    password: z.string(),
  })
  const { email, password } = bodySchema.parse(ctx.request.body)

  const normalizedEmail = email.toLowerCase()

  const [user] = await sql`
    select * from account where email = ${normalizedEmail}
  `
  if (!user) {
    ctx.status = 403
    ctx.body = { error: "Unauthorized", message: "Invalid email or password" }
    return
  }

  const passwordCorrect = await verifyPassword(password, user.passwordHash)

  if (!passwordCorrect) {
    ctx.status = 403
    ctx.body = { error: "Unauthorized", message: "Invalid email or password" }
    return
  }

  const token = await signJwt({
    userId: user.id,
    email: user.email,
    orgId: user.orgId,
  })

  ctx.body = { token }
})

auth.post("/request-password-reset", async (ctx: Context) => {
  try {
    const { email } = ctx.request.body as { email: string }
    const normalizedEmail = email.toLowerCase()
    const [user] = await sql`select id from account where email = ${normalizedEmail}`

    const ONE_HOUR = 60 * 60
    const token = await signJwt({ email: normalizedEmail }, ONE_HOUR)

    await sql`update account set recovery_token = ${token} where id = ${user.id}`

    const link = `${process.env.NEXT_PUBLIC_APP_URL}/reset-password?token=${token}`

    await sendEmail(RESET_PASSWORD(normalizedEmail, link))

    ctx.body = { ok: true }
  } catch (error) {
    console.error(error)
    // Do not send error message to client if email is not found
    ctx.body = {}
  }
})

auth.post("/reset-password", async (ctx: Context) => {
  const bodySchema = z.object({
    token: z.string(),
    password: z.string(),
  })
  const { token, password } = bodySchema.parse(ctx.request.body)

  const {
    payload: { email },
  } = await verifyJwt<{ email: string }>(token)

  const passwordHash = await hashPassword(password)

  const [user] = await sql`
    update account set password_hash = ${passwordHash} where email = ${email} returning *
  `

  const authToken = await signJwt({
    userId: user.id,
    email: user.email,
    orgId: user.orgId,
  })

  ctx.body = { token: authToken }
})

export default auth

