      const publicKey = {
        type: "public",
        projectId: project.id,
        apiKey: project.id,
      }
      sql`
        insert into api_key ${sql(publicKey)}
      `
      const privateKey = [
        {
          type: "private",
          projectId: project.id,
        },
      ]
      await sql`
        insert into api_key ${sql(privateKey)}
      `

      return { user, org }
    })

    const token = await signJwt({
      userId: user.id,
      email: user.email,
      orgId: org.id,
    })

    await sendVerifyEmail(email, name)
    await sendTelegramMessage(
      `<b>🔔 New signup from ${email}</b>
      ${name} is ${
        signupMethod === "signup"
          ? `building ${projectName} @ ${orgName} (${employeeCount}).`
          : "joining an org."
      }`,
      "users",
    )

    ctx.body = { token }
    return
  } else if (signupMethod === "join") {
    // Security fix: prevent unauthorized joining of an organization by orgId alone.
    // Require an invitation token that is validated before allowing the join.
    const bodySchemaJoin = z.object({
      email: z.string().email(),
      password: z.string().min(6),
      name: z.string(),
      orgId: z.string(),
      inviteToken: z.string(),
    })

    const { email, password, name, orgId, inviteToken } = bodySchemaJoin.parse(ctx.request.body)

    // Verify the invitation token is valid and matches the orgId
    let payload: { orgId: string; email?: string } | null = null
    try {
      payload = await verifyJwt<{ orgId: string; email?: string }>(inviteToken)
    } catch (error) {
      ctx.throw(403, "Invalid or expired invitation")
      return
    }

    if (!payload || payload.orgId !== orgId) {
      ctx.throw(403, "Invalid invitation for this organization")
      return
    }

    // Optionally, if the invitation is tied to a specific email, enforce it
    if (payload.email && payload.email !== email) {
      ctx.throw(403, "Invitation is for a different email")
      return
    }

    // Check that the org exists
    const [org] = await sql`select id from org where id = ${orgId}`
    if (!org) {
      ctx.throw(404, "Organization not found")
      return
    }

    const newUser = {
      name,
      passwordHash: await hashPassword(password),
      email,
      orgId,
      role: "member",
      verified: true,
    }
    const [user] = await sql`insert into account ${sql(newUser)} returning *`

    const token = await signJwt({
      userId: user.id,
      email: user.email,
      orgId,
    })

    ctx.body = { token }
    return
  }
})

